public class Room {
    private int roomNum;
    private int roomType;
    private int nightsReserved;

    public Room(int roomNum, int roomType, int nightsReserved) {
        this.roomNum = roomNum;
        this.roomType = roomType;
        this.nightsReserved = nightsReserved;
    }

    public int getRoomNum() { return roomNum; }
    public void setRoomNum(int roomNum) { this.roomNum = roomNum; }
    public int getRoomType() { return roomType; }
    public void setRoomType(int roomType) { this.roomType = roomType; }
    public int getNightsReserved() { return nightsReserved; }
    public void setNightsReserved(int nightsReserved) { this.nightsReserved = nightsReserved; }
}

public class Hostel {
    private Room[] allRooms;

    public Hostel(Room[] allRooms) {
        this.allRooms = allRooms;
    }

    public Room[] getAllRooms() { return allRooms; }
}

