tasks.instructions:
ממש את הפעולה orderRoom במחלקה Hostel:
public int orderRoom(int type, int nights)
הפעולה מוצאת את החדר הראשון במערך allRooms שעונה על התנאים האלה: פנוי, ומן הסוג type. הפעולה מעדכנת בחדר את מספר הלילות המבוקש שמופיע במשתנה nights, ומחזירה את מספר החדר. אם אין במערך חדר פנוי מן הסוג המבוקש, הפעולה מחזירה -1

tasks.solution:
public int orderRoom(int type, int nights) {
    for (int i = 0; i < allRooms.length; i++) {
        if (allRooms[i].getNightsReserved() == 0 && allRooms[i].getRoomType() == type) {
            allRooms[i].setNightsReserved(nights);
            return allRooms[i].getRoomNum();
        }
    }
    return -1;
}

public int[] floorIncome() {
    int[] sums = new int[3];
    for (int i = 0; i < allRooms.length; i++) {
        int floor = allRooms[i].getRoomNum() / 100;   // הספרה הראשונה
        sums[floor - 1] += allRooms[i].income();
    }
    return sums;
}

